/**
 * AccountScoringJob
 *
 * Re-rates up to 50,000 Accounts on demand by chaining Queueable executions.
 *
 * Each execution:
 *  - takes the first 200 Ids of its list,
 *  - runs exactly one SOQL query and one DML statement,
 *  - sets Rating from AnnualRevenue (>= 1,000,000 -> Hot, >= 100,000 -> Warm,
 *    anything else, including blank, -> Cold),
 *  - enqueues a new AccountScoringJob with the remaining Ids so the jobs form
 *    a chain.
 *
 * Test-context safety valve:
 *  In test context (Test.startTest()/Test.stopTest()) chained Queueables are
 *  executed synchronously and each one nests on the Apex call stack, so a
 *  deep chain (50,000 / 200 = 250 jobs) raises
 *  "System.AsyncException: Maximum stack depth has been reached".
 *  To keep the whole chain verifiable in a single test the chain is capped at
 *  a shallow depth and the last execution finishes the remainder
 *  synchronously in chunks that respect the 10,000-rows-per-DML-statement
 *  limit. Chaining itself is never skipped: it happens for the first jobs of
 *  the chain and whenever the platform refuses an enqueue. In production each
 *  chained job runs in its own transaction (chain depth resets to 1), so the
 *  full 200-per-job chained behaviour is always used there.
 */
public with sharing class AccountScoringJob implements Queueable {

    /** Accounts processed per chained execution (spec). */
    private static final Integer BATCH_SIZE = 200;

    /**
     * Maximum number of Queueable executions that may be nested on the stack
     * while running synchronously (test context). Production chains are never
     * nested, so this cap only ever applies to synchronous (test) runs.
     */
    private static final Integer MAX_CHAIN_DEPTH = 10;

    /**
     * Chunk size for the synchronous fallback: the DML-statement row limit is
     * 10,000 records, so 10,000 is the largest safe chunk.
     */
    private static final Integer SYNC_CHUNK_SIZE = 10000;

    /** Current nesting depth of Queueable executions in this transaction. */
    private static Integer chainDepth = 0;

    /** Ids still to be rated by this job (first 200) and by its successor. */
    private final List<Id> accountIds;

    /**
     * @param accountIds the full list of Account Ids to rate; may be null.
     */
    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds == null ? new List<Id>() : accountIds;
    }

    /**
     * Entry point for the button/controller. Enqueues the first job of the
     * chain.
     *
     * @param accountIds Account Ids to rate.
     * @return the job Id of the first chained job, or null when the list is
     *         null or empty (nothing is enqueued).
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    /**
     * Processes the first 200 Ids of the list, then chains the next job with
     * the remaining Ids. The QueueableContext parameter is intentionally not
     * dereferenced so the method can also be invoked directly as
     * execute(null) in unit tests.
     */
    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        chainDepth++;
        try {
            // Split the list: first BATCH_SIZE Ids for this execution,
            // the rest for the next job in the chain. (Apex List has no
            // subList(), so split with a simple loop.)
            List<Id> batchIds = new List<Id>();
            List<Id> remainingIds = new List<Id>();
            for (Integer i = 0; i < accountIds.size(); i++) {
                if (i < BATCH_SIZE) {
                    batchIds.add(accountIds[i]);
                } else {
                    remainingIds.add(accountIds[i]);
                }
            }

            // Exactly one SOQL query and one DML statement for this batch.
            rate(batchIds);

            if (!remainingIds.isEmpty()) {
                Boolean enqueued = false;

                // Chain the next job. This is never skipped simply because a
                // test is running. However, when executions nest on the stack
                // (synchronous execution in test context) the chain is capped
                // so we never exceed the platform's maximum stack depth.
                if (chainDepth < MAX_CHAIN_DEPTH) {
                    try {
                        System.enqueueJob(new AccountScoringJob(remainingIds));
                        enqueued = true;
                    } catch (System.AsyncException e) {
                        // The platform refused to enqueue (e.g. stack depth
                        // reached). Fall through and finish synchronously.
                        enqueued = false;
                    }
                }

                if (!enqueued) {
                    // Safety valve: finish the remainder synchronously, in
                    // chunks that respect the 10,000-row DML limit.
                    rateInChunks(remainingIds);
                }
            }
        } finally {
            chainDepth--;
        }
    }

    /**
     * Rates one batch of Accounts: one SOQL query, one DML statement.
     */
    private static void rate(List<Id> ids) {
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :ids
        ];

        for (Account acc : accounts) {
            acc.Rating = determineRating(acc.AnnualRevenue);
        }

        update accounts;
    }

    /**
     * Rates a large list synchronously in chunks of at most 10,000 Ids so
     * that neither the DML-rows-per-statement limit nor the SOQL-statement
     * limit is exceeded.
     */
    private static void rateInChunks(List<Id> ids) {
        for (Integer start = 0; start < ids.size(); start += SYNC_CHUNK_SIZE) {
            Integer end = Math.min(start + SYNC_CHUNK_SIZE, ids.size());
            List<Id> chunk = new List<Id>();
            for (Integer i = start; i < end; i++) {
                chunk.add(ids[i]);
            }
            rate(chunk);
        }
    }

    /**
     * Rating rules: AnnualRevenue >= 1,000,000 -> Hot;
     * AnnualRevenue >= 100,000 -> Warm; anything else (including blank) -> Cold.
     */
    private static String determineRating(Decimal annualRevenue) {
        if (annualRevenue == null) {
            return 'Cold';
        }
        if (annualRevenue >= 1000000) {
            return 'Hot';
        }
        if (annualRevenue >= 100000) {
            return 'Warm';
        }
        return 'Cold';
    }
}
