/**
 * Pure unit test for OpportunitiesService.applyDiscounts.
 *
 * No DML and no SOQL is executed. The Opportunities domain, the
 * OpportunitiesSelector and the unit of work are all mocked with
 * fflib_ApexMocks and injected via the Application factories:
 *
 *   - Application.Domain.setMock
 *   - Application.Selector.setMock
 *   - Application.UnitOfWork.setMock
 *
 * Fake ids are produced with fflib_IDGenerator.
 *
 * The tests pin down the following contract:
 *   - discountPercentage must be > 0 and <= 50, otherwise
 *     OpportunitiesService.OpportunitiesServiceException is thrown and
 *     neither the domain nor the unit of work is used;
 *   - null or empty ids: nothing is applied or committed;
 *   - otherwise the selected opportunities are wrapped in the Opportunities
 *     domain, applyDiscount is called once on it with the percentage
 *     unchanged and the unit of work from Application.UnitOfWork, and only
 *     after that is commitWork() called, once.
 */
@isTest
private class OpportunitiesServiceTest
{
	private static final Decimal VALID_DISCOUNT = 25;
	private static final Decimal MAXIMUM_VALID_DISCOUNT = 50;
	private static final Decimal DISCOUNT_OVER_MAXIMUM = 50.01;
	private static final Decimal ZERO_DISCOUNT = 0;
	private static final Decimal NEGATIVE_DISCOUNT = -10;

	/**
	 * Holds the ApexMocks test doubles for a single test case.
	 */
	private class TestDoubles
	{
		public fflib_ApexMocks mocks;
		public IOpportunities domain;
		public IOpportunitiesSelector selector;
		public fflib_ISObjectUnitOfWork unitOfWork;
	}

	private static TestDoubles givenMockedTestDoubles()
	{
		TestDoubles testDoubles = new TestDoubles();
		testDoubles.mocks = new fflib_ApexMocks();
		testDoubles.domain =
			(IOpportunities) testDoubles.mocks.mock(IOpportunities.class);
		testDoubles.selector =
			(IOpportunitiesSelector) testDoubles.mocks.mock(IOpportunitiesSelector.class);
		testDoubles.unitOfWork =
			(fflib_ISObjectUnitOfWork) testDoubles.mocks.mock(fflib_ISObjectUnitOfWork.class);

		Application.Domain.setMock(Opportunity.SObjectType, testDoubles.domain);
		Application.Selector.setMock(Opportunity.SObjectType, testDoubles.selector);
		Application.UnitOfWork.setMock(testDoubles.unitOfWork);
		return testDoubles;
	}

	private static Set<Id> givenOpportunityIds(Integer count)
	{
		Set<Id> opportunityIds = new Set<Id>();
		for (Integer i = 0; i < count; i++)
		{
			opportunityIds.add(fflib_IDGenerator.generate(Opportunity.SObjectType));
		}
		return opportunityIds;
	}

	private static List<Opportunity> givenOpportunities(Set<Id> opportunityIds)
	{
		List<Opportunity> opportunities = new List<Opportunity>();
		Integer index = 0;
		for (Id opportunityId : opportunityIds)
		{
			opportunities.add(
				new Opportunity(Id = opportunityId, Name = 'Opp ' + index, Amount = 1000 + index)
			);
			index++;
		}
		return opportunities;
	}

	/**
	 * Runs the service with a valid discount percentage and verifies that:
	 *   - the opportunities are selected with the given ids,
	 *   - applyDiscount is called once on the Opportunities domain with the
	 *     percentage unchanged and the unit of work from Application.UnitOfWork,
	 *   - commitWork is called once on the unit of work, and only after
	 *     applyDiscount (verified in order).
	 */
	private static void assertValidDiscountScenario(
		Set<Id> opportunityIds,
		Decimal discountPercentage
	)
	{
		TestDoubles testDoubles = givenMockedTestDoubles();
		List<Opportunity> selectedOpportunities = givenOpportunities(opportunityIds);

		testDoubles.mocks.startStubbing();
		testDoubles.mocks
			.when(testDoubles.selector.selectById(opportunityIds))
			.thenReturn(selectedOpportunities);
		testDoubles.mocks.stopStubbing();

		OpportunitiesService.applyDiscounts(opportunityIds, discountPercentage);

		// The opportunities were selected with the given ids, exactly once
		((IOpportunitiesSelector) testDoubles.mocks.verify(
			testDoubles.selector,
			fflib_ApexMocks.times(1)
		))
			.selectById(opportunityIds);

		// applyDiscount first (percentage unchanged, unit of work from the
		// factory), then commitWork - verified in order
		fflib_OrderedVerification inOrder = fflib_OrderedVerification.InOrder(
			testDoubles.mocks,
			new List<Object>{ testDoubles.domain, testDoubles.unitOfWork }
		);
		((IOpportunities) inOrder.verify(testDoubles.domain)).applyDiscount(
			discountPercentage,
			testDoubles.unitOfWork
		);
		((fflib_ISObjectUnitOfWork) inOrder.verify(testDoubles.unitOfWork)).commitWork();
	}

	/**
	 * Verifies that neither the domain (applyDiscount) nor the unit of work
	 * (commitWork) nor the selector (selectById) was used.
	 */
	private static void assertNothingAppliedOrCommitted(
		TestDoubles testDoubles,
		Set<Id> opportunityIds,
		Decimal discountPercentage
	)
	{
		((IOpportunities) testDoubles.mocks.verify(
			testDoubles.domain,
			fflib_ApexMocks.times(0)
		))
			.applyDiscount(discountPercentage, testDoubles.unitOfWork);
		((fflib_ISObjectUnitOfWork) testDoubles.mocks.verify(
			testDoubles.unitOfWork,
			fflib_ApexMocks.times(0)
		))
			.commitWork();
		((IOpportunitiesSelector) testDoubles.mocks.verify(
			testDoubles.selector,
			fflib_ApexMocks.times(0)
		))
			.selectById(opportunityIds);
	}

	/**
	 * Verifies that an OpportunitiesServiceException is thrown for an invalid
	 * discount percentage and that nothing is applied or committed.
	 */
	private static void assertInvalidDiscountThrows(
		Set<Id> opportunityIds,
		Decimal invalidDiscountPercentage
	)
	{
		TestDoubles testDoubles = givenMockedTestDoubles();

		Boolean expectedExceptionThrown = false;
		try
		{
			OpportunitiesService.applyDiscounts(opportunityIds, invalidDiscountPercentage);
		}
		catch (OpportunitiesService.OpportunitiesServiceException expectedException)
		{
			expectedExceptionThrown = true;
		}
		System.assert(
			expectedExceptionThrown,
			'Expected an OpportunitiesServiceException for a discount percentage of ' +
				invalidDiscountPercentage
		);

		assertNothingAppliedOrCommitted(testDoubles, opportunityIds, invalidDiscountPercentage);
	}

	@isTest
	static void testApplyDiscountsSelectsAppliesDiscountAndCommits()
	{
		assertValidDiscountScenario(givenOpportunityIds(2), VALID_DISCOUNT);
	}

	@isTest
	static void testApplyDiscountsAcceptsMaximumValidDiscount()
	{
		assertValidDiscountScenario(givenOpportunityIds(1), MAXIMUM_VALID_DISCOUNT);
	}

	@isTest
	static void testApplyDiscountsThrowsForDiscountOverMaximum()
	{
		assertInvalidDiscountThrows(givenOpportunityIds(1), DISCOUNT_OVER_MAXIMUM);
	}

	@isTest
	static void testApplyDiscountsThrowsForZeroDiscount()
	{
		assertInvalidDiscountThrows(givenOpportunityIds(1), ZERO_DISCOUNT);
	}

	@isTest
	static void testApplyDiscountsThrowsForNegativeDiscount()
	{
		assertInvalidDiscountThrows(givenOpportunityIds(1), NEGATIVE_DISCOUNT);
	}

	@isTest
	static void testApplyDiscountsThrowsForNullDiscount()
	{
		assertInvalidDiscountThrows(givenOpportunityIds(1), null);
	}

	@isTest
	static void testApplyDiscountsWithNullIdsDoesNothing()
	{
		TestDoubles testDoubles = givenMockedTestDoubles();
		Set<Id> opportunityIds = null;

		// Must complete without throwing
		OpportunitiesService.applyDiscounts(opportunityIds, VALID_DISCOUNT);

		assertNothingAppliedOrCommitted(testDoubles, opportunityIds, VALID_DISCOUNT);
	}

	@isTest
	static void testApplyDiscountsWithEmptyIdsDoesNothing()
	{
		TestDoubles testDoubles = givenMockedTestDoubles();
		Set<Id> opportunityIds = new Set<Id>();

		// Must complete without throwing
		OpportunitiesService.applyDiscounts(opportunityIds, VALID_DISCOUNT);

		assertNothingAppliedOrCommitted(testDoubles, opportunityIds, VALID_DISCOUNT);
	}
}
