public with sharing class Opportunities extends fflib_SObjectDomain
{
	/** Picklist value used for the "won" stage check. */
	private static final String STAGE_CLOSED_WON = 'Closed Won';

	/**
	 * Constructs the domain from the Opportunity records involved in the
	 * current trigger context (or passed in from a service/unit of work).
	 *
	 * @param sObjectList List of Opportunity records
	 **/
	public Opportunities(List<Opportunity> sObjectList)
	{
		super(sObjectList);
	}

	/**
	 * Standard inner class used by fflib_SObjectDomain.triggerHandler (and
	 * available to tests) to construct this domain class from a record list.
	 **/
	public class Constructor implements fflib_SObjectDomain.IConstructable
	{
		public fflib_SObjectDomain construct(List<SObject> sObjectList)
		{
			return new Opportunities(sObjectList);
		}
	}

	/**
	 * No-arg validation hook, kept for callers that invoke the legacy
	 * overload; it simply delegates to the main validation implementation
	 * (behaving like an insert, i.e. no pre-existing record state).
	 **/
	public override void onValidate()
	{
		onValidate((Map<Id, sObject>) null);
	}

	/**
	 * Validation rules, enforced by fflib_SObjectDomain.triggerHandler on
	 * before insert and before update (existingRecords is null on insert,
	 * and holds the pre-update state on update):
	 *
	 * 1. Amount must not be negative (insert and update).
	 * 2. On update, an opportunity whose stage was already Closed Won before
	 *    the update cannot have its Amount changed. Closing an opportunity as
	 *    won and changing its amount in the same update is allowed, because in
	 *    that case the stage was not yet Closed Won before the update.
	 *
	 * Both rules are bulk-safe (single pass over the records, no SOQL) and
	 * register the error only on the offending record's Amount field, via the
	 * domain's error(message, record, field) helper so fflib also records it
	 * in fflib_SObjectDomain.Errors for unit tests. Other records in the same
	 * DML operation are unaffected.
	 *
	 * @param existingRecords Read-only map of the records' prior state, or
	 *                        null when validating an insert
	 **/
	public override void onValidate(Map<Id, sObject> existingRecords)
	{
		for (Opportunity record : (List<Opportunity>) Records)
		{
			// Rule 1 - Amount cannot be negative (applies to insert and update)
			if (record.getPopulatedFieldsAsMap().containsKey('Amount') && record.Amount != null && record.Amount < 0)
			{
				error('Amount cannot be negative.', record, Opportunity.Amount);
			}

			// Rule 2 - Amount cannot change on a won opportunity (update only,
			// signalled by a non-null existingRecords map; no SOQL required).
			if (existingRecords != null)
			{
				Opportunity oldRecord = (Opportunity) existingRecords.get(record.Id);

				if (
					oldRecord != null &&
					STAGE_CLOSED_WON.equals(oldRecord.StageName) &&
					record.getPopulatedFieldsAsMap().containsKey('Amount') &&
					record.Amount != oldRecord.Amount
				)
				{
					error('Amount cannot change on a won opportunity.', record, Opportunity.Amount);
				}
			}
		}
	}
}
