public inherited sharing class ContactsSelector extends fflib_SObjectSelector
{
    /**
     * @description The SObject type this selector is responsible for.
     * @return The Contact SObjectType.
     */
    public virtual Schema.SObjectType getSObjectType()
    {
        return Contact.SObjectType;
    }

    /**
     * @description The fields this selector queries for.
     * @return The field list: Id, FirstName, LastName, Email, Title, AccountId.
     */
    public virtual List<Schema.SObjectField> getSObjectFieldList()
    {
        return new List<Schema.SObjectField>
        {
            Contact.Id,
            Contact.FirstName,
            Contact.LastName,
            Contact.Email,
            Contact.Title,
            Contact.AccountId
        };
    }

    /**
     * @description Returns the contacts with the given ids, in a single query,
     * with every field of the selector's field list populated.
     * @param contactIds The set of Contact ids to query for.
     * @return The matching contacts; an empty list if the given set is empty.
     */
    public List<Contact> selectById(Set<Id> contactIds)
    {
        // Guard clause: never issue a query for an empty id set.
        if (contactIds == null || contactIds.isEmpty())
        {
            return new List<Contact>();
        }

        // Build the query via the base class query factory so that the
        // selector's field list and default security/ordering settings are used.
        fflib_QueryFactory queryFactory = newQueryFactory();

        // Bind variable (injection-safe) filter on the record ids.
        queryFactory.setCondition('Id IN :contactIds');

        return (List<Contact>) Database.query(queryFactory.toSOQL());
    }
