public inherited sharing class OpportunitiesSelector extends fflib_SObjectSelector {
    public Schema.SObjectType getSObjectType() {
        return Opportunity.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Opportunity.Id,
            Opportunity.Name,
            Opportunity.AccountId,
            Opportunity.StageName,
            Opportunity.Amount,
            Opportunity.CloseDate
        };
    }

    public List<Opportunity> selectById(Set<Id> opportunityIds) {
        return (List<Opportunity>) selectSObjectsById(opportunityIds);
    }

    /**
     * Returns the open opportunities (IsClosed = false) of the given accounts,
     * highest Amount first, opportunities without an Amount after all the others,
     * and equal amounts by CloseDate ascending. At most maxRecords rows are
     * returned in one query. Each row carries the selector's standard field list
     * plus the parent account's Name (opp.Account.Name). The query is built via
     * fflib_QueryFactory seeded with this selector's SObjectType and field list,
     * so the selector's field list and security settings keep applying.
     */
    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        // Nothing to query, or an invalid limit: avoid an invalid SOQL statement
        if (accountIds == null || accountIds.isEmpty() || maxRecords == null || maxRecords <= 0) {
            return new List<Opportunity>();
        }

        // Seed the query factory with the selector's SObjectType and field list
        List<String> fieldNames = new List<String>();
        for (Schema.SObjectField field : getSObjectFieldList()) {
            fieldNames.add(field.getDescribe().getName());
        }
        fflib_QueryFactory queryFactory = new fflib_QueryFactory(getSObjectType(), fieldNames);

        // Only open opportunities belonging to the given accounts
        queryFactory.setCondition('IsClosed = false AND AccountId IN :accountIds');

        // Parent account Name on top of the selector's standard field list
        queryFactory.addField('Account.Name');

        // Highest Amount first, nulls (no Amount) after everything else,
        // ties resolved by earliest CloseDate
        queryFactory.addOrdering('Amount', 'DESC', 'LAST');
        queryFactory.addOrdering('CloseDate', 'ASC');

        queryFactory.setLimit(maxRecords);

        return (List<Opportunity>) Database.query(queryFactory.toSQLString());
    }
}
