// Note: in the deployed fflib version, getSObjectType() and getSObjectFieldList()
// are abstract and are implemented without the @Override keyword, while
// getSObjectFieldSetList() is virtual and must be marked @Override.

public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    /**
     * No-argument constructor used by the Application selector factory.
     *
     * includeFieldSetFields = true  -> every query also selects the fields of the
     *                                  Credit_Review field set (see getSObjectFieldSetList),
     *                                  so admins can extend it without code changes.
     * enforceCRUD = true            -> every query runs in user mode (WITH USER_MODE),
     *                                  so the platform enforces the running user's object,
     *                                  field and sharing access instead of leaking data.
     */
    public AccountsSelector() {
        super(true, true);
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
    }

    /**
     * Field set whose fields are appended to every query when includeFieldSetFields is
     * true (set in the constructor). Fields are read dynamically from the field set,
     * never hard-coded.
     */
    public override List<Schema.FieldSet> getSObjectFieldSetList() {
        return new List<Schema.FieldSet>{
            Schema.SObjectType.Account.fieldSets.getMap().get('Credit_Review')
        };
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    /**
     * Returns the accounts together with their Contacts child records in a single
     * query. The contact sub-query is built from ContactsSelector's field list so it
     * always uses (and stays in sync with) that selector's fields. The whole query is
     * executed in user mode, so a user who cannot read any selected field (on Account
     * or Contact) gets an exception rather than a partially filtered result.
     */
    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        // Account columns: this selector's field list + the Credit_Review field set fields.
        List<String> accountFieldPaths = toFieldPaths(getSObjectFieldList());
        accountFieldPaths.addAll(
            toFieldPaths(
                Schema.SObjectType.Account.fieldSets.getMap().get('Credit_Review').getFields()
            )
        );

        // Contact columns: taken from the ContactsSelector, not hard-coded here.
        List<String> contactFieldPaths = toFieldPaths(new ContactsSelector().getSObjectFieldList());

        String query = 'SELECT ' + String.join(accountFieldPaths, ', ') +
            ', (SELECT ' + String.join(contactFieldPaths, ', ') + ' FROM Contacts)' +
            ' FROM Account' +
            ' WHERE Id IN :accountIds';

        // User mode: platform enforces object, field and sharing access on the whole
        // statement, including the contact sub-query.
        return (List<Account>) Database.query(query, AccessLevel.USER_MODE);
    }

    private static List<String> toFieldPaths(List<Schema.SObjectField> fields) {
        List<String> fieldPaths = new List<String>();
        for (Schema.SObjectField field : fields) {
            fieldPaths.add(field.getDescribe().getName());
        }
        return fieldPaths;
    }

    private static List<String> toFieldPaths(List<Schema.FieldSetMember> fieldSetMembers) {
        List<String> fieldPaths = new List<String>();
        for (Schema.FieldSetMember member : fieldSetMembers) {
            fieldPaths.add(member.getFieldPath());
        }
        return fieldPaths;
    }
}
