/**
 * @description Creates Accounts and their related Contacts through a single
 *              fflib_SObjectUnitOfWork commit. No DML statements are performed
 *              in this class; all writes go through the unit of work's
 *              commitWork(). The unit of work is constructed with
 *              [Account, Contact] so that Accounts are inserted before
 *              Contacts during the single commit.
 */
public inherited sharing class AccountOnboardingService {

    /**
     * @description Creates one Account per map key and one Contact per last name
     *              in the corresponding list. All records are registered on a
     *              single fflib_SObjectUnitOfWork and committed exactly once.
     *              Each Contact is linked to its Account via an in-memory
     *              sObject relationship (contact.Account = account), which the
     *              platform resolves to the Account's Id at the time the Contact
     *              is inserted (Accounts are committed first).
     * @param  contactLastNamesByAccountName Map of Account Name -> list of
     *               Contact LastNames. Null or empty input returns an empty
     *               list and performs no writes.
     * @return The newly created Accounts, with their Ids populated after
     *         commitWork().
     */
    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        List<Account> newAccounts = new List<Account>();

        // Nothing to do: no unit of work is created and nothing is written.
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return newAccounts;
        }

        // Single unit of work for both object types. The order of the
        // SObjectTypes passed to the constructor determines commit order:
        // Accounts are inserted before Contacts, so the Contacts' in-memory
        // relationship references resolve to real Account Ids at insert time.
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<SObjectType>{ Account.SObjectType, Contact.SObjectType }
        );

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            // Account.Name is required; skip a null key rather than failing the whole transaction.
            if (accountName == null) {
                continue;
            }

            Account account = new Account(Name = accountName);
            uow.registerNew(account);
            newAccounts.add(account);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames == null) {
                continue;
            }

            for (String lastName : lastNames) {
                // Contact.LastName is required; skip a null entry to keep the commit valid.
                if (lastName == null) {
                    continue;
                }

                Contact contact = new Contact(LastName = lastName);
                // Set the relationship via an sObject reference. At commit time
                // the Account instance will already carry its Id (Accounts are
                // inserted first by the unit of work), so the platform resolves
                // Contact.AccountId from this reference during the Contact insert.
                contact.Account = account;
                uow.registerNew(contact);
            }
        }

        // Commit exactly once, and only if there is something to persist.
        if (!newAccounts.isEmpty()) {
            uow.commitWork();
        }

        // commitWork() populated the Ids on the registered Account instances.
        return newAccounts;
    }
}
