```apex
/**
 * GiftImportService
 *
 * Accepts one-off website gifts and routes them through NPSP's own data
 * import engine (NPSP Data Importer / BDI) instead of inserting Contacts and
 * Opportunities directly, so NPSP's contact matching, household creation and
 * donation processing rules apply.
 *
 * How it works
 * ------------
 * 1. For every gift we stage exactly one npsp__DataImport__c record, mapped
 *    onto NPSP's staging fields. The donor is always the primary contact
 *    (npsp__Donation_Donor__c = 'Contact1'), so NPSP matches or creates the
 *    contact per the org's npsp__Data_Import_Settings__c (which default to
 *    matching on first name, last name and email, and never matching
 *    existing donations). We deliberately do not touch the settings or any
 *    Contact/Opportunity records ourselves.
 * 2. The staged records are inserted in a single bulk DML call. NPSP's data
 *    import engine processes them synchronously, in this same transaction,
 *    and writes its results back onto each staged record:
 *    npsp__Status__c ('Imported' / 'Failed'), npsp__Contact1Imported__c,
 *    npsp__DonationImported__c and npsp__FailureInformation__c.
 * 3. We re-query the staged records and build one ImportResult per gift, in
 *    input order, from what NPSP wrote back.
 *
 * The staged npsp__DataImport__c records are never deleted, so they remain
 * in the org as the audit trail of what was imported.
 *
 * Bulk-safe: one bulk insert and one bulk SOQL per call regardless of gift
 * count (200 gifts in a single call is well within limits). A row NPSP
 * rejects is reported individually via npsp__FailureInformation__c and never
 * prevents the other rows from being processed.
 */
public with sharing class GiftImportService {

    /** Status value NPSP writes back to npsp__Status__c for a fully imported row. */
    private static final String STATUS_IMPORTED = 'Imported';

    /** Incoming gift from the website. */
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    /** Outcome for one gift, returned in input order. */
    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /**
     * Stage one NPSP Data Import record per gift, let NPSP's data import
     * engine process them synchronously in this transaction, and return one
     * ImportResult per gift, in input order.
     *
     * @param gifts the gifts received from the website; null or empty yields
     *              an empty result list
     * @return one ImportResult per gift, in input order
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        // A null or empty list returns an empty list.
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // 1. Stage one npsp__DataImport__c record per gift (single bulk list,
        //    no DML or SOQL inside the loop).
        List<npsp__DataImport__c> stagedRecords = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            // A null element must not blow up the batch; it stages an empty
            // row that NPSP itself will reject and report on.
            stagedRecords.add(stageGift(gift == null ? new WebGift() : gift));
        }

        // 2. Bulk DML. NPSP's data import engine processes the staged records
        //    synchronously in this transaction (contact matching, household
        //    creation, donation processing per the org's Data Import
        //    settings) and writes results back onto each record. Partial
        //    success is allowed so that a single rejected row can never stop
        //    the other gifts from being imported.
        Boolean stagingSucceeded = true;
        String stagingError;
        List<Database.SaveResult> saveResults;
        try {
            saveResults = Database.insert(stagedRecords, false);
        } catch (Exception e) {
            // The whole DML was rejected (e.g. the NPSP engine itself threw);
            // report every gift as failed rather than throwing at the caller.
            stagingSucceeded = false;
            stagingError = 'NPSP Data Import could not process the gifts: ' + e.getMessage();
        }

        // 3. Read back what NPSP wrote to the staged records.
        Map<Id, npsp__DataImport__c> processedRecords = new Map<Id, npsp__DataImport__c>();
        if (stagingSucceeded) {
            processedRecords.putAll([
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :stagedRecords
            ]);
        }

        // 4. Build one result per gift, in input order.
        for (Integer i = 0; i < gifts.size(); i++) {
            if (!stagingSucceeded) {
                results.add(failedResult(stagingError));
            } else if (!saveResults[i].isSuccess()) {
                // NPSP rejected the row outright (e.g. validation on the
                // staged record); carry its error without failing the rest.
                results.add(failedResult(buildSaveError(saveResults[i], i)));
            } else {
                results.add(buildResult(processedRecords.get(stagedRecords[i].Id)));
            }
        }

        return results;
    }

    /**
     * Map a website gift onto NPSP's staging fields. The donor is the primary
     * contact (Contact1); NPSP's own matching, household and donation
     * settings decide whether that contact is matched or created and how the
     * donation is processed. NPSP fills in the result fields afterwards.
     */
    private static npsp__DataImport__c stageGift(WebGift gift) {
        npsp__DataImport__c dataImport = new npsp__DataImport__c();
        dataImport.npsp__Contact1_Firstname__c = gift.firstName;
        dataImport.npsp__Contact1_Lastname__c = gift.lastName;
        dataImport.npsp__Contact1_Personal_Email__c = gift.email;
        dataImport.npsp__Donation_Amount__c = gift.amount;
        dataImport.npsp__Donation_Date__c = gift.giftDate;
        dataImport.npsp__Donation_Donor__c = 'Contact1';
        return dataImport;
    }

    /**
     * Build the caller-facing result for one gift from the processed
     * npsp__DataImport__c record NPSP wrote back to.
     */
    private static ImportResult buildResult(npsp__DataImport__c processedRecord) {
        if (processedRecord == null) {
            return failedResult('NPSP did not process the staged Data Import record.');
        }

        ImportResult result = new ImportResult();
        result.success = processedRecord.npsp__Status__c == STATUS_IMPORTED;
        result.contactId = processedRecord.npsp__Contact1Imported__c;
        result.opportunityId = processedRecord.npsp__DonationImported__c;

        if (!result.success) {
            // Carry NPSP's failure information; fall back to the status NPSP
            // left on the row if the detail field is empty.
            result.errorMessage = String.isNotBlank(processedRecord.npsp__FailureInformation__c)
                ? processedRecord.npsp__FailureInformation__c
                : 'NPSP reported status: ' + (processedRecord.npsp__Status__c == null
                    ? 'not processed'
                    : processedRecord.npsp__Status__c);
        }

        return result;
    }

    /** Build a failed result with the given error message. */
    private static ImportResult failedResult(String message) {
        ImportResult result = new ImportResult();
        result.success = false;
        result.errorMessage = message;
        return result;
    }

    /** Flatten a SaveResult's errors into one readable message. */
    private static String buildSaveError(Database.SaveResult saveResult, Integer giftIndex) {
        List<String> errors = new List<String>();
        for (Database.Error err : saveResult.getErrors()) {
            errors.add(err.getMessage());
        }
        return 'Gift ' + (giftIndex + 1) + ' could not be staged for NPSP Data Import: '
            + String.join(errors, '; ');
    }
}
