/**
 * Trigger Action (Trigger Actions Framework 0.3.4, no namespace) for the Contact
 * sObject_Trigger_Setting__mdt record. Registered via Trigger_Action__mdt records:
 *   - TA_Contact_PreventDuplicateEmail_BI (Before Insert)
 *   - TA_Contact_PreventDuplicateEmail_BU (Before Update)
 *
 * Rule: two Contacts of the same Account may not share an email address
 * (compared case-insensitively). Contacts without an Account or without an
 * Email are not checked.
 *
 * Behaviour:
 *  - A violating contact gets a record-level error via addError(), so valid
 *    contacts in the same save order still commit (partial saves work).
 *  - Within one save, the first contact (in trigger.new order) claiming an
 *    (AccountId, Email) pair is accepted; later ones are rejected.
 *  - On update, only contacts whose Email or AccountId changed are checked,
 *    so pre-existing (legacy) duplicates never block unrelated edits. A
 *    contact never conflicts with itself.
 *  - Bulk-safe: exactly one SOQL query per trigger execution.
 */
public inherited sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        enforce((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        enforce((List<Contact>) triggerNew, (List<Contact>) triggerOld);
    }

    private void enforce(List<Contact> newContacts, List<Contact> oldContacts) {
        Map<Id, Contact> oldById = oldContacts == null ?
            null :
            new Map<Id, Contact>(oldContacts);

        // Contacts eligible for checking, plus the (Account, Email) pairs they claim.
        List<Contact> toCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        Set<String> neededKeys = new Set<String>();

        // Ids of in-save contacts whose Email or AccountId changed. Their
        // database rows are stale (pre-update) and must be ignored when the
        // query results are evaluated; their new values are handled in memory.
        Set<Id> changedIds = new Set<Id>();

        for (Contact c : newContacts) {
            if (String.isBlank(c.Email) || c.AccountId == null) {
                continue;
            }
            if (oldById != null) {
                Contact old = oldById.get(c.Id);
                // Apex String == is case-insensitive, matching the rule's semantics.
                if (old != null && old.Email == c.Email && old.AccountId == c.AccountId) {
                    continue; // Email and AccountId unchanged: not checked.
                }
            }
            toCheck.add(c);
            changedIds.add(c.Id);
            accountIds.add(c.AccountId);
            emails.add(c.Email);
            neededKeys.add(key(c.AccountId, c.Email));
        }
        if (toCheck.isEmpty()) {
            return;
        }

        // Single SOQL query: existing contacts on the relevant accounts with any
        // of the relevant emails (SOQL email matching is case-insensitive).
        // The AccountId x Email cross product is filtered in memory by pair key.
        Set<String> existingKeys = new Set<String>();
        for (Contact existing : [
            SELECT AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds AND Email IN :emails
        ]) {
            String k = key(existing.AccountId, existing.Email);
            if (changedIds.contains(existing.Id)) {
                continue; // Stale pre-update row of a contact being checked in this save.
            }
            if (neededKeys.contains(k)) {
                existingKeys.add(k);
            }
        }

        // First contact in list order claiming a pair wins; later ones are rejected.
        Set<String> seenInSave = new Set<String>();
        for (Contact c : toCheck) {
            String k = key(c.AccountId, c.Email);
            if (seenInSave.contains(k) || existingKeys.contains(k)) {
                c.addError(ERROR_MESSAGE);
            } else {
                seenInSave.add(k);
            }
        }
    }

    private static String key(Id accountId, String email) {
        return String.valueOf(accountId) + '|' + email.toLowerCase();
    }
}
