/**
 * Trigger Action for the Trigger Actions Framework (TAF) on Case.
 *
 * Keeps Account.FB_Open_Case_Count__c equal to the number of open Cases
 * (IsClosed = false) belonging to the account. Handles insert, update
 * (close, reopen, move between accounts), delete and undelete. Cases
 * without an Account are ignored. An account whose last open case goes
 * away is set to 0, never blank.
 *
 * Budget: one aggregate SOQL query and one DML statement per trigger
 * execution, bulk-safe for 200+ records per chunk.
 */
public inherited sharing class TA_Case_RollupOpenCount
        implements TriggerAction.AfterInsert,
                   TriggerAction.AfterUpdate,
                   TriggerAction.AfterDelete,
                   TriggerAction.AfterUndelete {

    /** Accounts whose open case count must be recalculated. */
    private Set<Id> affectedAccountIds = new Set<Id>();

    public void afterInsert(List<SObject> triggerNew) {
        collectAccountIds(triggerNew);
        recompute();
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        // Recompute only when the count could actually change:
        // the case moved between accounts, or its closed status flipped.
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Case newCase = (Case) triggerNew[i];
            Case oldCase = (Case) triggerOld[i];
            if (newCase.AccountId != oldCase.AccountId
                    || newCase.IsClosed != oldCase.IsClosed) {
                if (newCase.AccountId != null) {
                    affectedAccountIds.add(newCase.AccountId);
                }
                if (oldCase.AccountId != null) {
                    affectedAccountIds.add(oldCase.AccountId);
                }
            }
        }
        recompute();
    }

    public void afterDelete(List<SObject> triggerOld) {
        collectAccountIds(triggerOld);
        recompute();
    }

    public void afterUndelete(List<SObject> triggerNew) {
        collectAccountIds(triggerNew);
        recompute();
    }

    private void collectAccountIds(List<SObject> records) {
        for (SObject record : records) {
            Id accountId = (Id) record.get('AccountId');
            if (accountId != null) {
                affectedAccountIds.add(accountId);
            }
        }
    }

    private void recompute() {
        if (affectedAccountIds.isEmpty()) {
            return;
        }

        // SOQL query 1 of 2 maximum: the true open case count per affected account.
        Map<Id, Integer> openCountByAccountId = new Map<Id, Integer>();
        for (AggregateResult result : [
                SELECT AccountId accountId, COUNT(Id) openCount
                FROM Case
                WHERE AccountId IN :affectedAccountIds
                AND IsClosed = false
                GROUP BY AccountId
        ]) {
            openCountByAccountId.put(
                (Id) result.get('accountId'),
                (Integer) result.get('openCount')
            );
        }

        // Accounts with no remaining open cases get 0, not blank.
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : affectedAccountIds) {
            accountsToUpdate.add(new Account(
                Id = accountId,
                FB_Open_Case_Count__c = openCountByAccountId.containsKey(accountId)
                    ? openCountByAccountId.get(accountId)
                    : 0
            ));
        }

        // One DML statement per trigger execution.
        update accountsToUpdate;
    }
}
