public inherited sharing class TA_Contact_Queries {

    private static TA_Contact_Queries instance;

    /**
     * Parent Accounts for the Contacts in the current trigger execution,
     * keyed by Id. Populated by TA_Contact_Queries.Service, which must run
     * first (Order__c 1) in the before insert context. The map is reloaded
     * on every trigger execution because later DML in the same transaction
     * can involve other Accounts.
     */
    public Map<Id, Account> accountsById { get; private set; }

    private TA_Contact_Queries() {
        this.accountsById = new Map<Id, Account>();
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Trigger action (TA_Contact_Queries_Service, Order__c 1) that loads the
     * parent Accounts of the trigger records into the singleton's map. Runs
     * on every trigger execution so the map always reflects the accounts
     * involved in the current execution, even after other DML in the same
     * transaction.
     */
    public inherited sharing class Service implements TriggerAction.BeforeInsert {

        public void beforeInsert(List<SObject> triggerNew) {
            TA_Contact_Queries.getInstance().loadAccounts(triggerNew);
        }
    }

    private void loadAccounts(List<SObject> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : contacts) {
            Id accountId = (Id) record.get(Schema.Contact.AccountId);
            if (accountId != null) {
                accountIds.add(accountId);
            }
        }

        this.accountsById = accountIds.isEmpty()
            ? new Map<Id, Account>()
            : new Map<Id, Account>([
                SELECT
                    AccountSource,
                    BillingStreet,
                    BillingCity,
                    BillingPostalCode,
                    BillingCountry
                FROM Account
                WHERE Id IN :accountIds
            ]);
    }
}
